import {validateV3Bundle,migrateV2ToV3} from './migration.js';
export function exportV3Bundle(state){return{schemaVersion:3,application:'LMN Knowledge System',exportedAt:new Date().toISOString(),knowledge:structuredClone(state.knowledge??[]),relations:structuredClone(state.relations??[]),representations:structuredClone(state.representations??[]),structureTemplates:structuredClone(state.structureTemplates??[]),structureInstances:structuredClone(state.structureInstances??[])}}
export function importV3Bundle(data,current){const incoming=(data.schemaVersion??data.schema_version)===3?data:migrateV2ToV3(data),validation=validateV3Bundle(incoming);if(!validation.valid)return{...validation,state:current};const state={...current};for(const key of['knowledge','relations','representations','structureTemplates','structureInstances'])state[key]=merge(current[key]??[],incoming[key]??[]);return{valid:true,errors:[],state}}
const merge=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,structuredClone(x)])).values()];
